<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {time} from '../format'
import {labelNames} from '../onchain'
import type {ChainView} from '../onchain'
import {flowKind,txLink,addressLink,tokenAmount} from '../flows'
import type {FlowView} from '../flows'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
const rows=ref<FlowView[]>([]);const chains=ref<ChainView[]>([]);const selected=ref<number|null>(null);const query=ref('');const important=ref(false)
async function load(signal?:AbortSignal){const [f,c]=await Promise.all([api<FlowView[]>('/api/flows',{signal}),api<ChainView[]>('/api/onchain',{signal})]);rows.value=f;chains.value=c}
const {error}=usePolling(load,10000)
const current=computed(()=>rows.value.find(r=>r.assetId===selected.value)??rows.value[0]);const chain=computed(()=>chains.value.find(c=>c.binding.assetId===current.value?.assetId));
const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return current.value?.transfers.filter(e=>(!important.value||['ProjectToExchange','ProjectOutflow','ExchangeInflow','ExchangeOutflow'].includes(e.kind))&&(!q||[e.transfer.from,e.transfer.to,e.transfer.transactionHash].some(s=>s.includes(q))))??[]})
const page=ref(1);const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10)));const visible=computed(()=>filtered.value.slice((Math.min(page.value,pages.value)-1)*10,Math.min(page.value,pages.value)*10));watch([query,important,selected],()=>page.value=1)
const retrying=ref(false);const actionMessage=ref('');async function retry(){if(!current.value||retrying.value)return;retrying.value=true;try{const r=await post<{message:string}>(`/api/flows/${current.value.assetId}/retry`);actionMessage.value=r.message;await load()}catch(e){actionMessage.value=e instanceof Error?e.message:String(e)}finally{retrying.value=false}}
</script>
<template><PageIntro eyebrow="BSC · TRANSFER EVIDENCE" title="看清每一笔流向。" description="原始事件、区块断点和归属证据一起保存。"><button class="replay-action" @click="load()">读取本地缓存</button></PageIntro>
<p v-if="actionMessage" role="status" class="radar-notice">{{actionMessage}}</p><p v-if="error" role="alert" class="radar-notice">{{error}}</p><p class="radar-notice">当前为单资产 BSC 自选试点，首次从最近 2,000 个确认区块开始，分段追赶，默认每 120 秒采集；等待 64 个区块仅是确认深度策略，不宣称绝对最终性。转入交易所不证明卖出，缺少标签也不代表安全。<RouterLink to="/onchain">核对链上身份与标签 →</RouterLink></p>
<div class="toolbar"><button v-for="r in rows" :key="r.assetId" class="text-button" @click="selected=r.assetId">{{r.symbol}} · {{r.summary.fresh?'观测新鲜':'追赶 / 待采集'}}</button></div>
<template v-if="current"><div class="stats"><StatCard label="近 1h 已观测事件" :value="current.summary.observedTransfers" :foot="current.summary.windowComplete?'区块范围覆盖至确认末块；不含未确认尾部':'时间范围或读取上限未完整覆盖，计数为下界'"/><StatCard label="项目类流出" :value="current.summary.projectOutflows" foot="只计已核对标签，不按大户余额猜测"/><StatCard label="交易所转入 / 转出" :value="`${current.summary.exchangeInflows} / ${current.summary.exchangeOutflows}`" foot="观测事件数量，非净流量或成交数量"/><StatCard label="观测质量" :value="current.summary.fresh?'有效':'等待 / 过期'" :foot="`截至 ${time(current.summary.throughTime)}`"/></div>
<section class="detail flow-detail"><h2>{{current.symbol}} · 采集范围与证据</h2><p>{{current.summary.caveat}}</p><p>链身份 {{current.summary.trustedIdentity?'匹配当前目录':'待核对'}} · 标签分类与合约存在性分别核验，不自动提升分类覆盖。</p><p v-if="current.cursor">起点 {{current.cursor.startBlock}}（{{time(current.cursor.startTime)}}） · 已保存至 {{current.cursor.nextBlock-1}} · RPC 观测链头 {{current.cursor.observedHead}} · 待追赶约 {{Math.max(0,current.cursor.observedHead-current.cursor.confirmationDepth-current.cursor.nextBlock+1)}} 块</p><p>下次尝试 {{time(current.attempt?.nextAttempt)}} · {{current.attempt?.halted?'锚点异常，已暂停':current.attempt?.error??'无采集错误'}}</p><button v-if="current.attempt?.error==='RPC 网络采集未完成；已保存断点不前移'" class="text-button" :disabled="retrying" @click="retry">申请网络失败重试（至少间隔两分钟，预算保持）</button><p>采集源 <a href="https://www.publicnode.com/" target="_blank" rel="noreferrer">PublicNode / 自定义 BSC RPC</a> · ERC20 Transfer 日志 · 展示最近 200 笔，统计读取近 24h 最多 10,000 笔。</p>
<div class="section-heading"><h2>转账明细</h2><span>{{filtered.length}} 笔</span></div><div class="toolbar"><label class="search"><input v-model="query" aria-label="搜索转账证据" placeholder="地址或交易哈希"></label><label class="checkbox"><input v-model="important" type="checkbox">仅显示已核对归属资金流</label></div>
<div class="table-scroll"><table><thead><tr><th>区块时间 / 交易</th><th>流出地址 / 标签版本</th><th>流入地址 / 标签版本</th><th>原始事件数量</th><th>归类 / 供应量占比</th></tr></thead><tbody><tr v-for="e in visible" :key="e.transfer.transactionHash+':'+e.transfer.logIndex"><td>{{time(e.transfer.blockTime)}}<small>区块 {{e.transfer.blockNumber}} · 日志 {{e.transfer.logIndex}}</small><a :href="txLink(e.transfer.transactionHash)??undefined" target="_blank" rel="noreferrer">{{e.transfer.transactionHash.slice(0,12)}}… ↗</a></td><td class="decision-reason"><a :href="addressLink(e.transfer.from)??undefined" target="_blank" rel="noreferrer">{{e.transfer.from}}</a><small>{{labelNames[e.fromType]}} · v{{e.fromLabelRevision}}</small><a v-if="e.fromEvidence" :href="e.fromEvidence" target="_blank" rel="noreferrer">标签证据 ↗</a></td><td class="decision-reason"><a :href="addressLink(e.transfer.to)??undefined" target="_blank" rel="noreferrer">{{e.transfer.to}}</a><small>{{labelNames[e.toType]}} · v{{e.toLabelRevision}}</small><a v-if="e.toEvidence" :href="e.toEvidence" target="_blank" rel="noreferrer">标签证据 ↗</a></td><td class="decision-reason">{{tokenAmount(e.transfer.rawAmount,chain?.sample?.decimals)}}<small>最小单位原值 {{e.transfer.rawAmount}}</small></td><td>{{flowKind[e.kind]??e.kind}}<small>{{e.supplyPercent==null?'Unknown':e.supplyPercent.toPrecision(5)+'%'}} · 非成交额</small></td></tr><tr v-if="!filtered.length"><td colspan="5" class="empty">当前本地观测或筛选范围内无记录；不能据此判断全链没有转账。</td></tr></tbody></table></div>
<div class="table-footer"><span>第 {{Math.min(page,pages)}} / {{pages}} 页 · 每页 10 笔</span><div><button :disabled="page<=1" @click="page=Math.max(1,page-1)">上一页</button><button :disabled="page>=pages" @click="page=Math.min(pages,page+1)">下一页</button></div></div></section><section class="detail flow-detail"><h2>主要持币地址 · 链上代码核验</h2><p>优先核验当前 Top10 地址，每 24h 更新。eth_getCode 只能证明指定区块是否存在代码，不能证明团队归属、签名人、锁仓用途或 LP 身份；不自动修改用户标签。</p><div class="table-scroll"><table><thead><tr><th>地址</th><th>核验结论</th><th>区块 / 时间</th><th>代码 SHA256 指纹</th></tr></thead><tbody><tr v-for="i in current.inspections" :key="i.address"><td class="decision-reason"><a :href="addressLink(i.address)??undefined" target="_blank" rel="noreferrer">{{i.address}}</a></td><td>{{i.conclusion}}</td><td>{{i.blockNumber}}<small>{{time(i.checkedAt)}}</small></td><td class="decision-reason">{{i.codeSha256}}<small>{{i.source}}</small></td></tr></tbody></table></div><p>官方分配说明没有给出足够的精确地址归属证据，大户归属继续待核对。<a href="https://docs.playariagame.com/tokenomics/allocation-and-vesting" target="_blank" rel="noreferrer">查看 ARIA 官方分配说明 ↗</a></p><RouterLink to="/onchain">核对并维护地址标签 →</RouterLink> · <RouterLink to="/watchtower">查看自选判断 →</RouterLink></section></template>
<section v-else class="detail"><p>等待已核对 BSC 身份与启用的自选资产。可先检查链上绑定与自选配置。</p></section></template>
<style scoped>.flow-detail{min-width:0}.flow-detail p,.flow-detail a{overflow-wrap:anywhere}.flow-detail td{white-space:normal;min-width:130px}.flow-detail td.decision-reason{min-width:200px;max-width:300px;overflow-wrap:anywhere}.flow-detail a{color:#82d2b0}</style>
